const $=id=>document.getElementById(id);let leads=[];
$('search').onclick=async()=>{let place=$('place').value.trim(),kind=$('kind').value.trim();if(!place||!kind){$('status').textContent='Enter a location and business type.';return}let box=$('cards');box.replaceChildren();$('status').textContent='Searching…';try{let geo=await(await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(place))).json();if(!geo.length)throw Error('Location not found');let b=geo[0].boundingbox,k=categoryPattern(kind),q=`[out:json][timeout:25];(nwr["name"]["shop"~"${k}"](around:15000,${geo[0].lat},${geo[0].lon});nwr["name"]["amenity"~"${k}"](around:15000,${geo[0].lat},${geo[0].lon});nwr["name"]["office"~"${k}"](around:15000,${geo[0].lat},${geo[0].lon});nwr["name"]["craft"~"${k}"](around:15000,${geo[0].lat},${geo[0].lon});nwr["name"]["healthcare"~"${k}"](around:15000,${geo[0].lat},${geo[0].lon});nwr["name"]["tourism"~"${k}"](around:15000,${geo[0].lat},${geo[0].lon});nwr["name"]["leisure"~"${k}"](around:15000,${geo[0].lat},${geo[0].lon}););out center 50;`;let data=await fetchOverpass(q);let broader=false;if(!data.elements?.length){const broad=`[out:json][timeout:25];(nwr["name"]["shop"](around:15000,${geo[0].lat},${geo[0].lon});nwr["name"]["amenity"](around:15000,${geo[0].lat},${geo[0].lon});nwr["name"]["office"](around:15000,${geo[0].lat},${geo[0].lon});nwr["name"]["craft"](around:15000,${geo[0].lat},${geo[0].lon}););out center 100;`;data=await fetchOverpass(broad);broader=true}leads=data.elements.map(e=>({name:e.tags.name,website:e.tags.website||e.tags['contact:website'],address:[e.tags['addr:housenumber'],e.tags['addr:street']].filter(Boolean).join(' ')})).sort((a,b)=>!!a.website-!!b.website);$('status').textContent=`${leads.length} ${broader?'other local business listings found; no exact category matches were found':'listings found'}. “No website listed” does not prove a site is absent.`;leads.forEach((lead,i)=>{let card=document.createElement('article');card.className='card';let title=document.createElement('h3');title.textContent=lead.name;let status=document.createElement('p');status.textContent=lead.website?'Website listed — review its quality':'No website listed — verify';let addr=document.createElement('p');addr.textContent=lead.address;let link=document.createElement('a');link.href=lead.website?(/^https?:\/\//i.test(lead.website)?lead.website:'https://'+lead.website):'https://www.google.com/search?q='+encodeURIComponent(lead.name+' '+place+' website');link.target='_blank';link.rel='noopener';link.textContent=lead.website?'Visit website':'Check for a website';let button=document.createElement('button');button.textContent='Draft email';button.onclick=()=>draft(i);card.append(title,status,addr,link,document.createElement('br'),button);box.append(card)})}catch(e){$('status').textContent='Search unavailable: '+e.message+'. Try another area or again later.'}};
function draft(i){let lead=leads[i],sender=$('sender').value.trim()||'[your business]';$('email').value=`Subject: A website idea for ${lead.name}\n\nHi ${lead.name} team,\n\nI came across your business while looking at local ${$('kind').value.trim()} businesses. [Add a genuine detail you noticed about the business or website.]\n\nI'm with ${sender}. We create clear, mobile-friendly websites that help local customers find what they need and get in touch. I'd love to share a few ideas tailored to ${lead.name}.\n\nWould you be open to a brief conversation next week?\n\nBest,\n[Your name]\n${sender}`;$('email').scrollIntoView({behavior:'smooth'})}
$('copy').onclick=async()=>{await navigator.clipboard.writeText($('email').value);$('copy').textContent='Copied!';setTimeout(()=>$('copy').textContent='Copy email',1500)};

function categoryPattern(input){const aliases={restaurants:'restaurant',cafes:'cafe',bakeries:'bakery','hair salons':'hairdresser|beauty','barbers':'barber|hairdresser',dentists:'dentist',plumbers:'plumber',electricians:'electrician','real estate agents':'estate_agent',florists:'florist',gyms:'fitness_centre|gym',hotels:'hotel'};const clean=input.toLowerCase().replace(/[^a-z0-9 ]/g,'').trim();if(/^restaur/.test(clean))return 'restaurant';const match=Object.keys(aliases).find(key=>distance(clean,key)<=2);return aliases[match]||clean.replace(/ies$/,'y').replace(/s$/,'').replace(/ +/g,'_')}



function distance(a,b){let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]===b[j-1]?0:1));row=next}return row[b.length]}


async function fetchOverpass(query){let last;for(const base of ['https://overpass.kumi.systems/api/interpreter','https://overpass-api.de/api/interpreter']){try{const response=await fetch(base+'?data='+encodeURIComponent(query));if(!response.ok)throw Error('Map service returned '+response.status);const data=await response.json();if(data.elements?.length)return data;last=data}catch(error){last=error}}if(last?.elements)return last;throw last||Error('Map search unavailable')}



